  public static void validateIPNet(Ip.IPNet msg) throws ProtoException {
    if (msg == null) {
      return;
    }
    // Validate mask (assert_le: 128)
    if (msg.getMask() > 128) {
      throw new ProtoException(
          ProtoException.INVALID_ARGUMENT,
          String.format("field mask must be <= 128, got: %s", msg.getMask()));
    }
  }

  public static void validateIPPort(Ip.IPPort msg) throws ProtoException {
    if (msg == null) {
      return;
    }
    // Validate port (assert_le: 65535)
    if (msg.getPort() > 65535) {
      throw new ProtoException(
          ProtoException.INVALID_ARGUMENT,
          String.format("field port must be <= 65535, got: %s", msg.getPort()));
    }
  }

