  // ============ Merge ============
  public static Ip.IPv4.Builder mergeIPv4(Ip.IPv4 dst, Ip.IPv4 src) {
    Ip.IPv4.Builder builder = dst.toBuilder();
    if (dst.getAddr() == 0) {
      builder.setAddr(src.getAddr());
    }
    return builder;
  }

  public static Ip.IPv6.Builder mergeIPv6(Ip.IPv6 dst, Ip.IPv6 src) {
    Ip.IPv6.Builder builder = dst.toBuilder();
    if (dst.getHigh() == 0) {
      builder.setHigh(src.getHigh());
    }
    if (dst.getLow() == 0) {
      builder.setLow(src.getLow());
    }
    return builder;
  }

  public static Ip.IPAddr.Builder mergeIPAddr(Ip.IPAddr dst, Ip.IPAddr src) {
    Ip.IPAddr.Builder builder = dst.toBuilder();
    if (dst.getAddressCase() == Ip.IPAddr.AddressCase.ADDRESS_NOT_SET) {
      switch (src.getAddressCase()) {
        case IPV4:
          builder.setIpv4(src.getIpv4());
          break;
        case IPV6:
          builder.setIpv6(src.getIpv6());
          break;
        default:
          break;
      }
    }
    return builder;
  }

  public static Ip.IPNet.Builder mergeIPNet(Ip.IPNet dst, Ip.IPNet src) {
    Ip.IPNet.Builder builder = dst.toBuilder();
    if (dst.getMask() == 0) {
      builder.setMask(src.getMask());
    }
    if (dst.getAddressCase() == Ip.IPNet.AddressCase.ADDRESS_NOT_SET) {
      switch (src.getAddressCase()) {
        case IPV4:
          builder.setIpv4(src.getIpv4());
          break;
        case IPV6:
          builder.setIpv6(src.getIpv6());
          break;
        default:
          break;
      }
    }
    return builder;
  }

  public static Ip.IPPort.Builder mergeIPPort(Ip.IPPort dst, Ip.IPPort src) {
    Ip.IPPort.Builder builder = dst.toBuilder();
    if (dst.getPort() == 0) {
      builder.setPort(src.getPort());
    }
    if (dst.getAddressCase() == Ip.IPPort.AddressCase.ADDRESS_NOT_SET) {
      switch (src.getAddressCase()) {
        case IPV4:
          builder.setIpv4(src.getIpv4());
          break;
        case IPV6:
          builder.setIpv6(src.getIpv6());
          break;
        default:
          break;
      }
    }
    return builder;
  }

  public static Ip.IPNets.Builder mergeIPNets(Ip.IPNets dst, Ip.IPNets src) {
    Ip.IPNets.Builder builder = dst.toBuilder();
    if (dst.getNetsList().isEmpty()) {
      builder.addAllNets(src.getNetsList());
    }
    return builder;
  }

  // ============ EnvVar ============
  public static Map<String, String> iPv4ToEnvVar(Ip.IPv4 msg) {
    Map<String, String> result = new HashMap<>();
    result.put("PROTO_I_PV4_ADDR", String.valueOf(msg.getAddr()));
    return result;
  }

  public static Ip.IPv4.Builder iPv4FromEnvVar(Map<String, String> env) {
    Ip.IPv4.Builder builder = Ip.IPv4.newBuilder();
    String val;
    val = env.get("PROTO_I_PV4_ADDR");
    if (val != null && !val.isEmpty()) {
      builder.setAddr(Integer.parseUnsignedInt(val));
    }
    return builder;
  }

